const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const mod = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{ .name = "app", .root_module = mod });
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    if (b.args) |args| run_cmd.addArgs(args);
    b.step("run", "Run the app").dependOn(&run_cmd.step);

    const tests = b.addTest(.{ .root_module = mod });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! 64-bit signed integer expression evaluator.
//!
//! Uses an iterative operator-precedence (shunting-yard) evaluator so that
//! deeply nested input cannot overflow the call stack. It accepts exactly:
//!
//!   expr    := term    (('+' | '-') term)*
//!   term    := unary   (('*' | '/' | '%') unary)*
//!   unary   := '-' unary | primary
//!   primary := NUMBER | '(' expr ')'

const std = @import("std");
const Allocator = std.mem.Allocator;

pub const EvalError = error{ Syntax, DivisionByZero, Overflow } || Allocator.Error;

const Op = enum {
    add,
    sub,
    mul,
    div,
    rem,
    neg,
    lparen,

    fn precedence(op: Op) u8 {
        return switch (op) {
            .lparen => 0,
            .add, .sub => 1,
            .mul, .div, .rem => 2,
            .neg => 3,
        };
    }
};

pub const Evaluator = struct {
    values: std.ArrayList(i64) = .empty,
    ops: std.ArrayList(Op) = .empty,

    pub fn deinit(self: *Evaluator, gpa: Allocator) void {
        self.values.deinit(gpa);
        self.ops.deinit(gpa);
        self.* = undefined;
    }

    pub fn eval(self: *Evaluator, gpa: Allocator, src: []const u8) EvalError!i64 {
        self.values.clearRetainingCapacity();
        self.ops.clearRetainingCapacity();

        var expect_operand = true;
        var i: usize = 0;
        while (true) {
            while (i < src.len and (src[i] == ' ' or src[i] == '\t')) i += 1;
            if (i == src.len) break;
            const c = src[i];
            if (expect_operand) {
                switch (c) {
                    '-' => try self.ops.append(gpa, .neg),
                    '(' => try self.ops.append(gpa, .lparen),
                    '0'...'9' => {
                        var n: i64 = 0;
                        while (i < src.len and std.ascii.isDigit(src[i])) : (i += 1) {
                            n = try checked(@mulWithOverflow(n, 10));
                            n = try checked(@addWithOverflow(n, src[i] - '0'));
                        }
                        try self.values.append(gpa, n);
                        expect_operand = false;
                        continue;
                    },
                    else => return error.Syntax,
                }
            } else {
                const op: Op = switch (c) {
                    '+' => .add,
                    '-' => .sub,
                    '*' => .mul,
                    '/' => .div,
                    '%' => .rem,
                    ')' => {
                        try self.reduceWhile(0);
                        if (self.ops.pop() == null) return error.Syntax;
                        i += 1;
                        continue;
                    },
                    else => return error.Syntax,
                };
                // Left-associative: reduce everything that binds at least as tightly.
                try self.reduceWhile(op.precedence());
                try self.ops.append(gpa, op);
                expect_operand = true;
            }
            i += 1;
        }
        if (expect_operand) return error.Syntax;
        try self.reduceWhile(0);
        if (self.ops.items.len != 0) return error.Syntax; // unmatched '('
        std.debug.assert(self.values.items.len == 1);
        return self.values.items[0];
    }

    /// Applies stacked operators whose precedence is at least `min`, stopping at '('.
    fn reduceWhile(self: *Evaluator, min: u8) EvalError!void {
        while (self.ops.getLastOrNull()) |top| {
            if (top == .lparen or top.precedence() < min) return;
            _ = self.ops.pop();
            try self.apply(top);
        }
    }

    fn apply(self: *Evaluator, op: Op) EvalError!void {
        const vals = &self.values;
        if (op == .neg) {
            const a = &vals.items[vals.items.len - 1];
            a.* = try checked(@subWithOverflow(0, a.*));
            return;
        }
        const b = vals.pop().?;
        const a = &vals.items[vals.items.len - 1];
        a.* = switch (op) {
            .add => try checked(@addWithOverflow(a.*, b)),
            .sub => try checked(@subWithOverflow(a.*, b)),
            .mul => try checked(@mulWithOverflow(a.*, b)),
            .div => blk: {
                if (b == 0) return error.DivisionByZero;
                if (b == -1 and a.* == std.math.minInt(i64)) return error.Overflow;
                break :blk @divTrunc(a.*, b);
            },
            .rem => blk: {
                if (b == 0) return error.DivisionByZero;
                if (b == -1) break :blk 0;
                break :blk @rem(a.*, b);
            },
            .neg, .lparen => unreachable,
        };
    }
};

fn checked(result: struct { i64, u1 }) error{Overflow}!i64 {
    if (result[1] != 0) return error.Overflow;
    return result[0];
}

/// Evaluates each line of `input`, printing its value or `error`; blank lines print nothing.
pub fn run(gpa: Allocator, input: []const u8, out: *std.Io.Writer) !void {
    var evaluator: Evaluator = .{};
    defer evaluator.deinit(gpa);

    var lines = std.mem.splitScalar(u8, input, '\n');
    while (lines.next()) |line| {
        if (std.mem.trim(u8, line, " \t").len == 0) continue;
        if (evaluator.eval(gpa, line)) |value| {
            try out.print("{d}\n", .{value});
        } else |err| switch (err) {
            error.OutOfMemory => return err,
            error.Syntax, error.DivisionByZero, error.Overflow => try out.writeAll("error\n"),
        }
    }
}

fn expectEval(src: []const u8, expected: EvalError!i64) !void {
    var e: Evaluator = .{};
    defer e.deinit(std.testing.allocator);
    const got = e.eval(std.testing.allocator, src);
    if (expected) |v| {
        try std.testing.expectEqual(v, try got);
    } else |_| {
        _ = got catch return;
        return error.TestExpectedError;
    }
}

test "arithmetic and precedence" {
    try expectEval("1 + 2 * 3", 7);
    try expectEval("(1 + 2) * 3", 9);
    try expectEval("1 + 2 * 3 - 4 / 2 % 3", 5);
    try expectEval("10 - 4 - 3", 3);
    try expectEval("-7 / 2", -3);
    try expectEval("-7 % 3", -1);
    try expectEval("7 % -3", 1);
    try expectEval("--5", 5);
    try expectEval("1 - -2", 3);
    try expectEval("-(2 + 3)", -5);
    try expectEval("((((7))))", 7);
}

test "limits" {
    try expectEval("-9223372036854775807 - 1", std.math.minInt(i64));
    try expectEval("(-9223372036854775807 - 1) % -1", 0);
    try expectEval("(-9223372036854775807 - 1) / -1", error.Overflow);
    try expectEval("-(-9223372036854775807 - 1)", error.Overflow);
    try expectEval("9223372036854775807 + 1", error.Overflow);
    try expectEval("9223372036854775808", error.Overflow);
    try expectEval("-9223372036854775808", error.Overflow);
    try expectEval("1 / 0", error.DivisionByZero);
    try expectEval("5 % 0", error.DivisionByZero);
}

test "syntax errors" {
    for ([_][]const u8{ "1 +", "abc", "()", "1 2", "+1", "(1 + 2", "1 + 2)", ")(", "1 -", "- ", "2 * * 3", "1\r" }) |src| {
        try expectEval(src, error.Syntax);
    }
}

//! LRU cache simulator. Every command runs in O(1) expected time.
//!
//! Entries live in an array hash map; each entry's value carries the links of an
//! intrusive doubly linked list (by entry index) kept in recency order. The array
//! hash map deletes by swapping with the last entry, which leaves no tombstones,
//! so long SET/DEL/evict churn does not degrade lookups.

const std = @import("std");
const Allocator = std.mem.Allocator;

const Index = u32;
const none: Index = std.math.maxInt(Index);

const Node = struct {
    value: []const u8,
    prev: Index = none,
    next: Index = none,
};

pub const Cache = struct {
    capacity: usize,
    map: std.StringArrayHashMapUnmanaged(Node) = .empty,
    /// Most recently used.
    head: Index = none,
    /// Least recently used.
    tail: Index = none,

    pub fn init(capacity: usize) Cache {
        return .{ .capacity = capacity };
    }

    pub fn deinit(self: *Cache, gpa: Allocator) void {
        self.map.deinit(gpa);
        self.* = undefined;
    }

    pub fn size(self: *const Cache) usize {
        return self.map.count();
    }

    /// Keys and values are borrowed and must outlive the cache.
    pub fn set(self: *Cache, gpa: Allocator, key: []const u8, value: []const u8) Allocator.Error!void {
        const gop = try self.map.getOrPut(gpa, key);
        const idx: Index = @intCast(gop.index);
        if (gop.found_existing) {
            gop.value_ptr.value = value;
            self.unlink(idx);
        } else {
            gop.value_ptr.* = .{ .value = value };
        }
        self.pushFront(idx);
        if (self.map.count() > self.capacity) self.remove(self.tail);
    }

    pub fn get(self: *Cache, key: []const u8) ?[]const u8 {
        const idx: Index = @intCast(self.map.getIndex(key) orelse return null);
        self.unlink(idx);
        self.pushFront(idx);
        return self.nodes()[idx].value;
    }

    /// Returns whether the key was present.
    pub fn del(self: *Cache, key: []const u8) bool {
        const idx: Index = @intCast(self.map.getIndex(key) orelse return false);
        self.remove(idx);
        return true;
    }

    fn nodes(self: *const Cache) []Node {
        return self.map.values();
    }

    fn remove(self: *Cache, idx: Index) void {
        self.unlink(idx);
        const last: Index = @intCast(self.map.count() - 1);
        self.map.swapRemoveAt(idx);
        if (idx == last) return;
        // The former last entry now lives at `idx`; repoint its neighbours.
        const moved = self.nodes()[idx];
        if (moved.prev != none) self.nodes()[moved.prev].next = idx else self.head = idx;
        if (moved.next != none) self.nodes()[moved.next].prev = idx else self.tail = idx;
    }

    fn unlink(self: *Cache, idx: Index) void {
        const all = self.nodes();
        const node = &all[idx];
        if (node.prev != none) all[node.prev].next = node.next else self.head = node.next;
        if (node.next != none) all[node.next].prev = node.prev else self.tail = node.prev;
        node.prev = none;
        node.next = none;
    }

    fn pushFront(self: *Cache, idx: Index) void {
        const all = self.nodes();
        all[idx].prev = none;
        all[idx].next = self.head;
        if (self.head != none) all[self.head].prev = idx else self.tail = idx;
        self.head = idx;
    }
};

/// Runs the command script in `input`; keys and values borrow from it.
pub fn run(gpa: Allocator, input: []const u8, out: *std.Io.Writer) !void {
    var lines = std.mem.splitScalar(u8, input, '\n');
    const first = lines.next() orelse return;
    const capacity = std.fmt.parseInt(usize, std.mem.trim(u8, first, " \t\r"), 10) catch return error.InvalidCapacity;

    var cache: Cache = .init(capacity);
    defer cache.deinit(gpa);
    try cache.map.ensureTotalCapacity(gpa, @min(capacity + 1, 1 << 20));

    while (lines.next()) |raw| {
        const line = std.mem.trimEnd(u8, raw, "\r");
        var tokens = std.mem.splitScalar(u8, line, ' ');
        const op = tokens.next() orelse continue;
        if (std.mem.eql(u8, op, "SET")) {
            const key = tokens.next() orelse continue;
            const value = tokens.next() orelse continue;
            try cache.set(gpa, key, value);
        } else if (std.mem.eql(u8, op, "GET")) {
            const key = tokens.next() orelse continue;
            try out.print("{s}\n", .{cache.get(key) orelse "NULL"});
        } else if (std.mem.eql(u8, op, "DEL")) {
            const key = tokens.next() orelse continue;
            try out.writeAll(if (cache.del(key)) "1\n" else "0\n");
        } else if (std.mem.eql(u8, op, "SIZE")) {
            try out.print("{d}\n", .{cache.size()});
        }
    }
}

fn expectOutput(input: []const u8, expected: []const u8) !void {
    const gpa = std.testing.allocator;
    var out: std.Io.Writer.Allocating = .init(gpa);
    defer out.deinit();
    try run(gpa, input, &out.writer);
    try std.testing.expectEqualStrings(expected, out.written());
}

test "spec example" {
    try expectOutput("2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n", "1\nNULL\n2\n");
}

test "overwrite refreshes recency" {
    try expectOutput("2\nSET a 1\nSET b 2\nSET a 9\nSET c 3\nGET a\nGET b\nGET c", "9\nNULL\n3\n");
}

test "delete, size, capacity one" {
    try expectOutput("3\nSET x 1\nDEL x\nDEL x\nSIZE\nGET x\n", "1\n0\n0\nNULL\n");
    try expectOutput("1\nSET a 1\nSET b 2\nGET a\nGET b\nSIZE\n", "NULL\n2\n1\n");
}

test "eviction churn keeps links consistent" {
    const gpa = std.testing.allocator;
    var cache: Cache = .init(3);
    defer cache.deinit(gpa);
    const keys = [_][]const u8{ "a", "b", "c", "d", "e" };
    for (0..200) |i| {
        const k = keys[(i * 7) % keys.len];
        switch (i % 4) {
            0, 1 => try cache.set(gpa, k, k),
            2 => _ = cache.get(k),
            else => _ = cache.del(k),
        }
        try std.testing.expect(cache.size() <= 3);
        var n: usize = 0;
        var it = cache.head;
        while (it != none) : (it = cache.nodes()[it].next) n += 1;
        try std.testing.expectEqual(cache.size(), n);
    }
}

//! `app <wordfreq|lru|calc>`: each subcommand reads all of stdin and writes its results to stdout.

const std = @import("std");
const Io = std.Io;

const wordfreq = @import("wordfreq.zig");
const lru = @import("lru.zig");
const calc = @import("calc.zig");

const Command = enum { wordfreq, lru, calc };

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    // Process-lifetime allocations; everything is freed at exit.
    const gpa = init.arena.allocator();

    var args = init.minimal.args.iterate();
    _ = args.next();
    const name = args.next() orelse usage();
    const command = std.meta.stringToEnum(Command, name) orelse usage();

    var in_buf: [64 * 1024]u8 = undefined;
    var stdin = Io.File.stdin().readerStreaming(io, &in_buf);
    const input = try stdin.interface.allocRemaining(gpa, .unlimited);

    var out_buf: [64 * 1024]u8 = undefined;
    var stdout = Io.File.stdout().writerStreaming(io, &out_buf);
    const out = &stdout.interface;

    switch (command) {
        .wordfreq => try wordfreq.run(gpa, input, out),
        .lru => try lru.run(gpa, input, out),
        .calc => try calc.run(gpa, input, out),
    }
    try out.flush();
}

fn usage() noreturn {
    std.debug.print("usage: app <wordfreq|lru|calc>\n", .{});
    std.process.exit(2);
}

test {
    _ = wordfreq;
    _ = lru;
    _ = calc;
}

//! Word frequency counter: prints the ten most frequent ASCII-letter words.

const std = @import("std");
const Allocator = std.mem.Allocator;

pub const top_n = 10;

const Entry = struct {
    word: []const u8,
    count: u64,

    /// Count descending, then word ascending (byte order).
    fn before(_: void, a: Entry, b: Entry) bool {
        if (a.count != b.count) return a.count > b.count;
        return std.mem.order(u8, a.word, b.word) == .lt;
    }
};

/// Counts words in `input` and writes the top entries to `out`.
/// `input` is lowercased in place so that map keys can borrow from it.
pub fn run(gpa: Allocator, input: []u8, out: *std.Io.Writer) !void {
    var counts: std.StringHashMapUnmanaged(u64) = .empty;
    defer counts.deinit(gpa);

    var i: usize = 0;
    while (i < input.len) {
        if (!std.ascii.isAlphabetic(input[i])) {
            i += 1;
            continue;
        }
        const start = i;
        while (i < input.len and std.ascii.isAlphabetic(input[i])) : (i += 1) {
            input[i] = std.ascii.toLower(input[i]);
        }
        const gop = try counts.getOrPut(gpa, input[start..i]);
        if (gop.found_existing) gop.value_ptr.* += 1 else gop.value_ptr.* = 1;
    }

    var top: [top_n]Entry = undefined;
    const n = selectTop(&counts, &top);
    for (top[0..n]) |e| try out.print("{d} {s}\n", .{ e.count, e.word });
}

/// Keeps the best `top.len` entries in sorted order via insertion; O(distinct * top_n).
fn selectTop(counts: *const std.StringHashMapUnmanaged(u64), top: []Entry) usize {
    var n: usize = 0;
    var it = counts.iterator();
    while (it.next()) |kv| {
        const e: Entry = .{ .word = kv.key_ptr.*, .count = kv.value_ptr.* };
        if (n == top.len and !Entry.before({}, e, top[n - 1])) continue;
        var pos = if (n < top.len) n else top.len - 1;
        if (n < top.len) n += 1;
        while (pos > 0 and Entry.before({}, e, top[pos - 1])) : (pos -= 1) top[pos] = top[pos - 1];
        top[pos] = e;
    }
    return n;
}

fn expectOutput(input: []const u8, expected: []const u8) !void {
    const gpa = std.testing.allocator;
    const buf = try gpa.dupe(u8, input);
    defer gpa.free(buf);
    var out: std.Io.Writer.Allocating = .init(gpa);
    defer out.deinit();
    try run(gpa, buf, &out.writer);
    try std.testing.expectEqualStrings(expected, out.written());
}

test "spec example" {
    try expectOutput("The cat and the hat.", "2 the\n1 and\n1 cat\n1 hat\n");
}

test "separators and empty" {
    try expectOutput("don't stop_me 4now, now-NOW", "3 now\n1 don\n1 me\n1 stop\n1 t\n");
    try expectOutput("", "");
    try expectOutput("123 \xff\xc3(", "");
}

test "top ten with ties" {
    try expectOutput(
        "zeta eta theta iota kappa lambda mu nu xi omicron pi rho alpha beta alpha",
        "2 alpha\n1 beta\n1 eta\n1 iota\n1 kappa\n1 lambda\n1 mu\n1 nu\n1 omicron\n1 pi\n",
    );
}
